package cn.dreamingfish.launcher.servers;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import java.net.*;import java.io.*;import static org.junit.jupiter.api.Assertions.*;
class ServerStoreTest {
 @TempDir Path root;
 @Test void favoritesSurviveReopenAndUseRevision()throws Exception {var store=new ServerStore(root);var initial=store.read();var saved=store.save(initial.revision(),null,"朋友的服务器",new ServerAddress("play.example.org",25565));assertEquals(1,saved.servers().size());assertEquals(saved,new ServerStore(root).read());assertThrows(IOException.class,()->store.require(initial.revision(),saved.servers().getFirst().id()));assertThrows(IOException.class,()->store.save(initial.revision(),null,"过期",new ServerAddress("other.example.org",25565)));var entry=saved.servers().getFirst();var updated=store.save(saved.revision(),entry.id(),"改名",entry.address());assertEquals("改名",updated.servers().getFirst().name());assertTrue(store.remove(updated.revision(),entry.id()).servers().isEmpty());assertTrue(Files.isRegularFile(root.resolve("player-servers/previous.json")));}
 @Test void rejectsCommandsUrlsAndInvalidPorts(){for(String host:new String[]{"https://example.org","x --password y","example.org/path","x\ncommand","../x","[::1]:25565"})assertThrows(IllegalArgumentException.class,()->new ServerAddress(host,25565));assertThrows(IllegalArgumentException.class,()->new ServerAddress("localhost",0));assertEquals("[::1]:25565",new ServerAddress("::1",25565).authority());assertEquals("play.example.org:25565",new ServerAddress("play.example.org",25565).authority());}
 @Test void singleUseDirectConnectionHasVersionFloorAndLiteralArguments()throws Exception {var address=new ServerAddress("play.example.org",25565);assertEquals(java.util.List.of("java","Main","--quickPlayMultiplayer","play.example.org:25565"),address.command(java.util.List.of("java","Main"),"1.20.6"));assertThrows(IOException.class,()->address.command(java.util.List.of("java","Main"),"1.12.2"));assertThrows(IOException.class,()->address.command(java.util.List.of("java","Main","--quickPlayMultiplayer","elsewhere"),"1.20.6"));}
 @Test void realTcpProbeReportsReachabilityAndFailureSeparately()throws Exception {try(var server=new ServerSocket(0,1,InetAddress.getLoopbackAddress());var probe=new TcpServerProbe()){var result=probe.probe(new ServerAddress(server.getInetAddress().getHostAddress(),server.getLocalPort()));assertEquals("REACHABLE",result.state());assertTrue(result.latencyMs()>=0);int port=server.getLocalPort();server.close();assertNotEquals("REACHABLE",probe.probe(new ServerAddress(InetAddress.getLoopbackAddress().getHostAddress(),port)).state());}}
}
